import { IngestPipeline, MaterializedView, sql, Api } from "@514labs/moose-lib";

// User Activity Event Model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Ingest Pipeline - optimized for user-based queries
export const UserActivityPipeline = new IngestPipeline<UserActivity>(
  "UserActivity",
  {
    ingestApi: true,
    stream: true,
    table: {
      // Order by user_id first for "activity counts per user over date range" queries
      orderByFields: ["user_id", "event_ts"]
    },
  }
);

// Materialized View for Action Type Aggregations
interface ActionDurationSummary {
  action: string;
  total_duration_ms: number;
  event_count: number;
}

export const actionDurationSummary = new MaterializedView<ActionDurationSummary>({
  tableName: "ActionDurationSummary",
  materializedViewName: "action_duration_summary_mv",
  orderByFields: ["action"],
  selectStatement: sql`
    SELECT
      action,
      sum(duration_ms) AS total_duration_ms,
      count() AS event_count
    FROM UserActivity
    GROUP BY action
  `,
  selectTables: [UserActivityPipeline.table!],
});

// Analytics API for user activity counts over date range
interface UserActivityCountsInput {
  user_id?: string;
  start_date?: string;
  end_date?: string;
}

interface UserActivityCountsRow {
  user_id: string;
  activity_count: number;
}

export const userActivityCounts = new Api<UserActivityCountsInput, UserActivityCountsRow>(
  "user-activity-counts",
  async ({ user_id, start_date, end_date }, { client, sql }) => {
    let query = sql`
      SELECT
        user_id,
        count() AS activity_count
      FROM UserActivity
      WHERE 1=1
    `;

    if (user_id) {
      query = sql`${query} AND user_id = ${user_id}`;
    }

    if (start_date) {
      query = sql`${query} AND event_ts >= toDateTime('${start_date}')`;
    }

    if (end_date) {
      query = sql`${query} AND event_ts <= toDateTime('${end_date}')`;
    }

    query = sql`${query} GROUP BY user_id ORDER BY activity_count DESC`;

    const result = await client.query.execute(query);
    return await result.json();
  }
);

